def prime_gap_record(limit: int) -> int:
    """Largest gap between consecutive primes up to `limit`."""
    primes: list[int] = sieve_primes(limit)
    best: int = 0
    for i in range(1, len(primes)):
        gap: int = primes[i] - primes[i - 1]
        if gap > best:
            best = gap
    return best

